cd /gin && cat > /gin/zz_probe_test.go <<'EOF'
package gin

import (
	"errors"
	"fmt"
	"testing"
)

type probeErr string

func (e probeErr) Error() string { return string(e) }

type ptrErr struct{ s string }

func (e *ptrErr) Error() string { return e.s }

func TestZZProbe(t *testing.T) {
	inner := probeErr("some error")
	sentinel := errors.New("sentinel")

	// 1. pointer gin.Error, direct
	e1 := &Error{Err: inner, Type: ErrorTypeAny}
	t.Log("1 Is(ptr,direct):", errors.Is(e1, inner))
	var te probeErr
	t.Log("1 As(ptr,direct):", errors.As(e1, &te))

	// 2. pointer gin.Error, wrapped with fmt.Errorf
	e2 := fmt.Errorf("wrapped: %w", &Error{Err: inner, Type: ErrorTypeAny})
	t.Log("2 Is(ptr,wrap):", errors.Is(e2, inner))
	var te2 probeErr
	t.Log("2 As(ptr,wrap):", errors.As(e2, &te2))

	// 3. value gin.Error, direct
	e3 := Error{Err: inner, Type: ErrorTypeAny}
	t.Log("3 Is(val,direct):", errors.Is(e3, inner))
	var te3 probeErr
	t.Log("3 As(val,direct):", errors.As(e3, &te3))

	// 4. value gin.Error, wrapped
	e4 := fmt.Errorf("wrapped: %w", Error{Err: inner, Type: ErrorTypeAny})
	t.Log("4 Is(val,wrap):", errors.Is(e4, inner))
	var te4 probeErr
	t.Log("4 As(val,wrap):", errors.As(e4, &te4))

	// 5. errors.As to *Error through fmt wrap
	var ge *Error
	t.Log("5 As(*Error,wrap):", errors.As(e2, &ge), ge != nil)

	// 6. errors.As to *Error direct
	var ge2 *Error
	t.Log("6 As(*Error,direct):", errors.As(e1, &ge2))

	// 7. errors.Is with sentinel inner (pointer)
	e7 := &Error{Err: sentinel, Type: ErrorTypeAny}
	t.Log("7 Is(sentinel,ptr):", errors.Is(e7, sentinel))
	t.Log("7 Is(sentinel,ptr,wrap):", errors.Is(fmt.Errorf("w: %w", e7), sentinel))

	// 8. errors.Is with sentinel inner (value)
	e8 := Error{Err: sentinel, Type: ErrorTypeAny}
	t.Log("8 Is(sentinel,val):", errors.Is(e8, sentinel))
	t.Log("8 Is(sentinel,val,wrap):", errors.Is(fmt.Errorf("w: %w", e8), sentinel))

	// 9. errors.Unwrap chain
	t.Log("9 Unwrap(wrap):", errors.Unwrap(e2) != nil)
	t.Log("9 Unwrap(ginErr):", errors.Unwrap(e1))

	// 10. errors.As with pointer-receiver target through gin.Error
	pe := &ptrErr{s: "p"}
	e10 := fmt.Errorf("w: %w", &Error{Err: pe, Type: ErrorTypeAny})
	var peOut *ptrErr
	t.Log("10 As(*ptrErr,wrap):", errors.As(e10, &peOut))

	// 11. Is(ginErr pointer itself)
	t.Log("11 Is(ptr,ptr):", errors.Is(e1, e1))

	// 12. Is value gin.Error as target
	t.Log("12 Is(ptr,valtarget):", errors.Is(e1, Error{Err: inner, Type: ErrorTypeAny}))
}
EOF
go test -run TestZZProbe -v . 2>&1 | head -60

