func zzGenRoutes(rnd *rand.Rand, n int) []zzRoute {
	static := []string{"a", "b", "c", "x1", "y2", "whoami", "search", "user"}
	var out []zzRoute
	for i := 0; i < n; i++ {
		nseg := 1 + rnd.Intn(4)
		var segs []string
		for j := 0; j < nseg; j++ {
			switch r := rnd.Intn(10); {
			case r < 5:
				segs = append(segs, static[rnd.Intn(len(static))])
			case r < 9:
				segs = append(segs, fmt.Sprintf(":p%d", j))
			default:
				if j == nseg-1 {
					segs = append(segs, fmt.Sprintf("*c%d", j))
				} else {
					segs = append(segs, static[rnd.Intn(len(static))])
				}
			}
		}
		out = append(out, zzRoute{path: "/" + strings.Join(segs, "/"), segs: segs})
	}
	return out
}

func zzConcrete(rnd *rand.Rand, r zzRoute) (string, map[string]string) {
	var parts []string
	vals := map[string]string{}
	for _, s := range r.segs {
		switch {
		case strings.HasPrefix(s, ":"):
			v := fmt.Sprintf("v%d", rnd.Intn(1000))
			vals[s[1:]] = v
			parts = append(parts, v)
		case strings.HasPrefix(s, "*"):
			v := fmt.Sprintf("/rest%d/end", rnd.Intn(1000))
			vals[s[1:]] = v
			parts = append(parts, strings.TrimPrefix(v, "/"))
		default:
			parts = append(parts, s)
		}
	}
	return "/" + strings.Join(parts, "/"), vals
}

