func buildTree(routes []string) *node {
	tree := &node{}
	for _, r := range routes {
		tree.addRoute(r, fakeHandler(r))
	}
	return tree
}

func TestScratchCIStaticAndWildcard(t *testing.T) {
	routes := []string{
		"/search/static",
		"/search/other",
		"/search/:query",
		"/cmd/:tool/",
		"/cmd/static/",
		"/cmd/static/extra",
		"/src/*filepath",
		"/w/♬",
		"/w/♭/",
		"/w/:p",
	}
	tree := buildTree(routes)
	tests := []struct {
		in    string
		out   string
		found bool
	}{
		{"/SEARCH/STATIC", "/search/STATIC", true},
		{"/SEARCH/OTHER", "/search/OTHER", true},
		{"/SEARCH/QUERY", "/search/QUERY", true},
		{"/SEARCH/QUERY/", "/search/QUERY", true},
		{"/CMD/TOOL/", "/cmd/TOOL/", true},
		{"/CMD/STATIC/", "/cmd/STATIC/", true},
		{"/CMD/STATIC/EXTRA", "/cmd/STATIC/EXTRA", true},
		{"/SRC/FILE/PATH", "/src/FILE/PATH", true},
		{"/W/♬", "/w/♬", true},
		{"/W/♭", "/w/♭/", true},
		{"/W/XYZ", "/w/XYZ", true},
	}
	for _, tc := range tests {
		out, found := tree.findCaseInsensitivePath(tc.in, true)
		if found != tc.found || string(out) != tc.out {
			t.Errorf("in=%q got %q,%v want %q,%v", tc.in, string(out), found, tc.out, tc.found)
		}
	}
}

// cross-check: whenever getValue finds a handler, findCaseInsensitivePath on the
// same (case-corrected) path must find something too.
func TestScratchCICrossCheck(t *testing.T) {
	routes := []string{
		"/",
		"/hi",
		"/b/",
		"/ABC/",
		"/search/:query",
		"/cmd/:tool/",
		"/src/*filepath",
		"/x",
		"/x/y",
		"/y/",
		"/y/z",
		"/0/:id",
		"/0/:id/1",
		"/1/:id/",
		"/1/:id/2",
		"/aa",
		"/a/",
		"/doc",
		"/doc/go_faq.html",
		"/doc/go1.html",
		"/doc/go/away",
		"/no/a",
		"/no/b",
		"/Π",
		"/u/apfêl/",
		"/u/äpfêl/",
		"/u/öpfêl",
		"/v/Äpfêl/",
		"/v/Öpfêl",
		"/w/♬",
		"/w/♭/",
		"/w/𠜎",
		"/w/𠜏/",
	}
	tree := buildTree(routes)
	// For every registered route, uppercase the leading static part and check
	// case-insensitive lookup still resolves.
	for _, r := range routes {
		up := strings.ToUpper(r)
		out, found := tree.findCaseInsensitivePath(up, true)
		if !found {
			t.Errorf("route %q: uppercase %q not found", r, up)
			continue
		}
		// the result must itself resolve to a handler
		var params Params
		sk := getSkippedNodes()
		_ = sk
		v := tree.getValue(string(out), &params, sk, false)
		if v.handlers == nil {
			t.Errorf("route %q: uppercase %q -> %q does not resolve", r, up, string(out))
		}
	}
}

