package gin

import (
	"fmt"
	"math/rand"
	"strings"
	"testing"
)

type zzR struct {
	path string
	segs []string
}

func zzGen(rnd *rand.Rand) zzR {
	static := []string{"a", "ab", "abc", "b", "c", "x", "xy", "whoami", "search", "user", "cmd", "doc"}
	pre := []string{"", "u", "us", "user_", "con", "x"}
	nseg := 1 + rnd.Intn(4)
	var segs []string
	for j := 0; j < nseg; j++ {
		switch r := rnd.Intn(12); {
		case r < 6:
			segs = append(segs, static[rnd.Intn(len(static))])
		case r < 10:
			segs = append(segs, pre[rnd.Intn(len(pre))]+fmt.Sprintf(":p%d", j))
		default:
			if j == nseg-1 {
				segs = append(segs, fmt.Sprintf("*c%d", j))
			} else {
				segs = append(segs, static[rnd.Intn(len(static))])
			}
		}
	}
	return zzR{path: "/" + strings.Join(segs, "/"), segs: segs}
}

// build a concrete request path for route r, plus expected params
func zzConcrete(rnd *rand.Rand, r zzR) (string, []Param) {
	var parts []string
	var ps []Param
	for _, s := range r.segs {
		switch {
		case strings.HasPrefix(s, "*"):
			v := fmt.Sprintf("/r%d/e", rnd.Intn(1000))
			ps = append(ps, Param{s[1:], v})
			parts = append(parts, strings.TrimPrefix(v, "/"))
		case strings.Contains(s, ":"):
			idx := strings.Index(s, ":")
			v := fmt.Sprintf("v%d", rnd.Intn(1000))
			ps = append(ps, Param{s[idx+1:], v})
			parts = append(parts, s[:idx]+v)
		default:
			parts = append(parts, s)
		}
	}
	return "/" + strings.Join(parts, "/"), ps
}

func TestZZFuzz2(t *testing.T) {
	rnd := rand.New(rand.NewSource(7))
	bad, checked := 0, 0
	for iter := 0; iter < 4000; iter++ {
		var routes []zzR
		seen := map[string]bool{}
		for i := 0; i < 2+rnd.Intn(8); i++ {
			r := zzGen(rnd)
			if seen[r.path] {
				continue
			}
			seen[r.path] = true
			routes = append(routes, r)
		}
		tree := &node{}
		ok := true
		for _, r := range routes {
			func() {
				defer func() { if rec := recover(); rec != nil { ok = false } }()
				tree.addRoute(r.path, fakeHandler(r.path))
			}()
			if !ok {
				break
			}
		}
		if !ok {
			continue
		}
		for _, r := range routes {
			req, want := zzConcrete(rnd, r)
			value := tree.getValue(req, getParams(), getSkippedNodes(), false)
			if value.handlers == nil {
				continue
			}
			matched := value.fullPath
			if !strings.Contains(matched, ":") && !strings.Contains(matched, "*") {
				continue
			}
			checked++
			// expected params for the matched route: recompute from matched path and req
			exp := zzExpected(matched, req)
			if exp == nil {
				continue
			}
			if value.params == nil || len(*value.params) != len(exp) {
				bad++
				if bad <= 8 {
					fmt.Printf("PARAM COUNT: req=%q matched=%q got=%v want=%v\n", req, matched, value.params, exp)
				}
				continue
			}
			for i := range exp {
				if (*value.params)[i] != exp[i] {
					bad++
					if bad <= 8 {
						fmt.Printf("PARAM VAL: req=%q matched=%q got=%v want=%v\n", req, matched, *value.params, exp)
					}
					break
				}
			}
		}
	}
	fmt.Println("checked:", checked, "bad:", bad)
}

// zzExpected computes the params that should be produced when req matches matched.
func zzExpected(matched, req string) []Param {
	msegs := strings.Split(strings.TrimPrefix(matched, "/"), "/")
	rsegs := strings.Split(strings.TrimPrefix(req, "/"), "/")
	if len(msegs) != len(rsegs) {
		return nil
	}
	var out []Param
	for i, s := range msegs {
		switch {
		case strings.HasPrefix(s, "*"):
			out = append(out, Param{s[1:], "/" + rsegs[i]})
		case strings.Contains(s, ":"):
			idx := strings.Index(s, ":")
			if !strings.HasPrefix(rsegs[i], s[:idx]) {
				return nil
			}
			out = append(out, Param{s[idx+1:], rsegs[i][idx:]})
		default:
			if s != rsegs[i] {
				return nil
			}
		}
	}
	return out
}
